#pragma once
#include "d/t60conv.h"
#include "d/actor/d_a_enemy_anm_t60.h"

/* Hand edits (2026-11-18; the tool's table above is its first pass): the probe geometry back to every
 * step (not a decision), the five timers once per frame on the first step, the state hold (an action / mode entered on
 * an earlier step first runs next frame), gravity x dt with the exact-arc term (nz_t60_arc), the stuck count on the
 * tick30 step from the frame-start position (nz_t60_frame_start), the lighting (settingTevStruct, after the dispatch in
 * both branches) on the tick30 step (A's order). */

/* true60 (the per-step movement rule,'s exact arc for inline gravity): the y offset dv x (1 - dt) / 2 for this step's gravity change */
static inline f32 nz_t60_arc(f32 dv) {
#ifdef T60C_NEGCTRL
    (void)dv;
    return 0.0f;
#else
    if (!t60c::on())
        return 0.0f;
    return gabi::fmuls_ppc(gabi::fmuls_ppc(dv, gabi::fsubs_ppc(1.0f, t60::dt())), 0.5f);
#endif
}

/* the frame-start position (the first step's old.pos), kept in the host table over the frame's steps */
static inline s32& nz_t60_fs_entry(const void* k, int axis) {
    const u32 tag = t60c::frameTag();
    t60c::AddEntry& e = t60c::s_add.at(t60c::key(k, 30 + axis) ^ 0x1000000000000000ull, tag);
    if (e.tag != tag) {
        e.tag = tag;
        e.given = 0;
    }
    return e.given;
}
static inline void nz_t60_frame_start(const void* k, const cXyz* stepStart) {
#ifndef T60C_NEGCTRL
    if (!t60c::on() || !t60::first_step())
        return;
    const f32 v[3] = {stepStart->x, stepStart->y, stepStart->z};
    for (int a = 0; a < 3; a++)
        __builtin_memcpy(&nz_t60_fs_entry(k, a), &v[a], 4);
#else
    (void)k, (void)stepStart;
#endif
}
/* the frame's displacement (frame start - pos) into out; false at dt 1 (the caller takes the original old.pos - pos) */
static inline bool nz_t60_frame_delta(const void* k, const cXyz* pos, cXyz* out) {
#ifndef T60C_NEGCTRL
    if (!t60c::on())
        return false;
    f32 v[3];
    for (int a = 0; a < 3; a++)
        __builtin_memcpy(&v[a], &nz_t60_fs_entry(k, a), 4);
    out->x = gabi::fsubs_ppc(v[0], pos->x);
    out->y = gabi::fsubs_ppc(v[1], pos->y);
    out->z = gabi::fsubs_ppc(v[2], pos->z);
    return true;
#else
    (void)k, (void)pos, (void)out;
    return false;
#endif
}

/* the arc offset as a speed for posMove's step (p += v dt): arc / dt; 0 at dt 1 */
static inline f32 nz_t60_arc_speed(f32 arc) {
    return t60c::on() ? arc / t60::dt() : 0.0f;
}

/* true60 (nz option b): the damage and bomb states run the unconverted callDamageMove /
 * callBombMove: a frame that starts in one of them takes the whole form (d/t60_whole.h: the tick30 step runs the original
 * execute at dt 1 from the frame-start state, the earlier steps are picture steps). The frame-start action is latched on
 * the first step (heldInt site 5); a state entered during a per-step frame starts the whole form next frame. dt 1: no. */
#include "d/t60_objw.h"
static inline bool nz_t60_whole_frame(const nz_class* i_this) {
#ifdef T60C_NEGCTRL
    (void)i_this;
    return false;
#else
    if (!t60c::on())
        return false;
    const s32 a0 = t60c::heldInt((s32)(u8)i_this->mAction, 5, i_this);
    return a0 == NZ_ACTION_DAMAGE || a0 == NZ_ACTION_BOMB;
#endif
}

/* true60 (hand): a state read of the motion after the dispatch: the first step's read, held over the frame's later steps
 * (the state A moves with all frame); dt 1: the live read */
static inline s32 nz_t60_mot(s32 live, int site, const void* k) { return t60c::heldInt(live, site, k); }

/* true60 (hand): the crawl edge turn (angle.x += 0x1000 per 30 Hz frame, a share per step) taken on the
 * frame's first step: kept in the host table (key site 33) so the first-step body check (nz option b) can test the
 * spin-attack condition angle.x == 0 on the angle A tests (after the frame's whole turn: the first step's share plus the
 * rest of the frame's 0x1000). Per actor, reset on every first step; dt 1: no projection. */
static inline s32& nz_t60_turn_entry(const void* k) {
    const u32 tag = t60c::frameTag();
    t60c::AddEntry& e = t60c::s_add.at(t60c::key(k, 33) ^ 0x1000000000000000ull, tag);
    if (e.tag != tag) {
        e.tag = tag;
        e.given = 0;
    }
    return e.given;
}
static inline void nz_t60_turn_note(const void* k, bool turned) {
#ifndef T60C_NEGCTRL
    if (!t60c::on() || !t60::first_step())
        return;
    nz_t60_turn_entry(k) = turned ? 1 : 0;
#else
    (void)k, (void)turned;
#endif
}
/* the angle.x the frame's body check reads: the live angle plus the frame's remaining edge turn (first step only) */
static inline s16 nz_t60_check_angle_x(const void* k, s16 live) {
#ifndef T60C_NEGCTRL
    if (!t60c::on() || !t60::first_step() || nz_t60_turn_entry(k) == 0)
        return live;
    return (s16)(live + (s16)(0x1000 - t60c::share(0x1000)));
#else
    (void)k;
    return live;
#endif
}

/* true60 (the first-step push rule, as ks's ks_t60_cc_begin; 2026-11-20): the Co push (mStts.m_cc_move) the frame's
 * first step sees is the last tick30 collision Move's, A's; at N > 1 an in-between Move rewrites (or clears) it from the
 * step's half-frame positions. So every posMove of the frame takes the first step's push (fopAcM_posMove moves dt of it:
 * the frame's total is A's push). Float bits held per instance (heldInt sites 40-42). Pair ttf7n2 f190: B consumed half
 * of the push (step 2 saw it cleared), rat 47C56A90 4.5 short. dt 1: nothing. */
static inline u32 nz_t60_fbits(f32 v) { u32 b; __builtin_memcpy(&b, &v, 4); return b; }
static inline f32 nz_t60_bitsf(u32 b) { f32 v; __builtin_memcpy(&v, &b, 4); return v; }
template <class V> static inline void nz_t60_cc_frame(const void* k, V* cc) {
#ifndef T60C_NEGCTRL
    if (!t60c::on())
        return;
    const f32 x = nz_t60_bitsf((u32)t60c::heldInt((s32)nz_t60_fbits((f32)cc->x), 40, k));
    const f32 y = nz_t60_bitsf((u32)t60c::heldInt((s32)nz_t60_fbits((f32)cc->y), 41, k));
    const f32 z = nz_t60_bitsf((u32)t60c::heldInt((s32)nz_t60_fbits((f32)cc->z), 42, k));
    cc->x = x;
    cc->y = y;
    cc->z = z;
#else
    (void)k, (void)cc;
#endif
}

/* true60 (2026-11-20, pair rat 47C5A3E8 f234): BG_check snaps y to ground + mBgOffsetY. A's one
 * BG check per frame sees the previous frame's offset (the cLib_addCalc2 after it moves the offset for the next frame);
 * at N > 1 a later step's BG check saw the share the earlier step added (2.25 at the crawl -> JUMP frame: the whole jump
 * 2.25 high, the landing one step early). So BG_check takes the frame-start offset: the first step's read, held over
 * the frame (float bits, heldInt site 44). dt 1: the live read. */
static inline f32 nz_t60_bg_ofs(f32 live, const void* k) {
    return nz_t60_bitsf((u32)t60c::heldInt((s32)nz_t60_fbits(live), 44, k));
}
/* true60 (first-step AI-timer, t60once; same pair, f247): the jump's wall stop and landing read the acch flags; A reads the last frame's
 * BG check. At N > 1 a later step read the earlier step's ground hit and bounced mid-frame (B: speedF 17.5 on f247,
 * mode 21 a frame longer). So the jump reads the frame-start flags (the first step's read, held: heldInt site 45): the
 * landing is decided on the first step after the tick30 BG check that hit the ground, and applied once there. */
static inline u32 nz_t60_jump_flags(u32 live, const void* k) {
    return (u32)t60c::heldInt((s32)live, 45, k);
}

/* true60 (the exact arc for speedF; pair rat 47C5A3E8 f249-f251): a per-step speedF
 * ease (cLib_addCalc0 at dt) before the step's move: A moves the whole frame at the frame-end speed, B at each step's
 * eased speed (BOUNCE 15 -> 10: 12.5 + 10 over two half steps, 1.25 more a frame). The step's ease change dv is noted
 * (host memory, this actor and step) and the move adds dv x (1 - dt) / 2 along the forward direction, so N steps end
 * where one does. Eases made at dt 1 (the crawl's whole first step, the bounce entry) note nothing. dt 1: nothing. */
struct NzT60Ramp {
    const void* actor;
    u32 step;
    f32 dv;
};
inline NzT60Ramp nzT60Ramp = {nullptr, 0, 0.0f};
static inline void nz_t60_ease0F(nz_class* i_this, f32 scale, f32 maxStep) {
#ifndef T60C_NEGCTRL
    const f32 before = i_this->speedF;
    cLib_addCalc0(&i_this->speedF, scale, maxStep);
    if (!t60c::on() || t60::dt() == 1.0f)
        return;
    const u32 st = t60_step_counter();
    if (nzT60Ramp.actor != i_this || nzT60Ramp.step != st)
        nzT60Ramp = NzT60Ramp{i_this, st, 0.0f};
    nzT60Ramp.dv = gabi::fadds_ppc(nzT60Ramp.dv, gabi::fsubs_ppc((f32)i_this->speedF, before));
#else
    cLib_addCalc0(&i_this->speedF, scale, maxStep);
#endif
}
/* the noted ramp's arc dv x (1 - dt) / 2 for this actor and step (taken once); 0 when none */
static inline f32 nz_t60_ramp_take(const void* k) {
#ifndef T60C_NEGCTRL
    if (!t60c::on() || nzT60Ramp.actor != k || nzT60Ramp.step != t60_step_counter())
        return 0.0f;
    const f32 dv = nzT60Ramp.dv;
    nzT60Ramp.actor = nullptr;
    return nz_t60_arc(dv);
#else
    (void)k;
    return 0.0f;
#endif
}
